from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.scheduler.base_listeners import SuiteListener


class EventsGroupCloser(SuiteListener):

    def end_test(self, test, result):
        Notifier().close_active_group()

    def end_suite(self, suite, result):
        Notifier().close_active_group()


events_group_closer = EventsGroupCloser
